#nullable enable
using Marten;
using Wolverine;
using EmailOutbox.Contracts;
using EmailOutbox.Views;

namespace EmailOutbox.Slices.EmailOutbox;

/// <summary>
/// The Automated Trigger of send-email: <c>Event(s) -> View -> TRIGGER -> Command -> Event(s)</c>.
///
/// It is a peer of a person at a screen — it reads a View and issues a Command. It never takes an event as
/// input and never appends one; <c>Event -> Processor -> Event</c> is the classic anti-pattern.
///
/// <see cref="IQuerySession"/> and not <see cref="IDocumentSession"/> on purpose: that makes "a trigger
/// never appends" a compile error rather than a convention. The events come from the decider, reached
/// through the command.
///
/// Returns <see cref="Task"/> and NOT a result object. Wolverine treats a handler's return value as a
/// CASCADING MESSAGE with no opt-out, so a report returned from a fire-and-forget run is unroutable and
/// takes the whole outgoing batch with it. If a human needs to see what a run did, log it or give the run
/// its own operational route.
///
/// What wakes this is NOT here: see SendEmailWakeup.
/// </summary>
public static class EmailProcessor
{
    public static async Task Handle(
        RunSendEmail message,
        IQuerySession session,
        IMessageBus bus,
        ILogger logger,
        CancellationToken cancellation)
    {
        // THE WORK SELECTION. Read the View, issue the Command per pending row. Nothing here knows or
        // cares what woke it — that is the whole point of the Run message being the seam.
        var pending = await session.Query<EmailsToSend>()
            .Where(r => r.Status == EmailsToSend.Pending)
            .OrderBy(r => r.Id)
            .ToListAsync(cancellation);

        var sent = 0;
        var refused = new List<string>();

        foreach (var row in pending)
        {
            // InvokeAsync, not PublishAsync: the trigger wants the outcome back so a refusal is visible
            // rather than silently dropped. The decider is what actually holds the rules.
            var outcome = await bus.InvokeAsync<SendOutcome>(new SendEmail(row.EmailId), cancellation);

            if (outcome.WasSent) sent++;
            else refused.Add(outcome.Rule!);
        }

        // ALWAYS log, including a run that did nothing. A trigger is silent whenever there is no work, so
        // logging only the interesting case makes "alive with nothing to do" and "dead" byte-identical —
        // and that ambiguity has already hidden one broken wakeup mechanism in this kit.
        logger.LogInformation(
            "send-email run: {Pending} pending, {Sent} sent, {Refused} refused{Rules}.",
            pending.Count, sent, refused.Count,
            refused.Count == 0 ? "" : $" ({string.Join(", ", refused.Distinct())})");
    }
}
